styl:
.iq-section-hero-bg--iq-hero-section{background-position:{{ background_position }};background-repeat:no-repeat;background-size:cover;border-collapse:separate!important;border-radius:{{ radius }}!important}
.iq-section-hero-bg--iq-hero-section.bgr-image{background-image:url({{ bg_image }});background-color:{{ background_color }};background-position:{{ background_position }};background-repeat:no-repeat;background-size:cover}
.iq-section-hero-bg--iq-hero-media,.iq-section-hero-bg--iq-hero-content{vertical-align:top}
@media screen and (max-width:600px){.iq-section-hero-bg--iq-hero-content.text-pad-small{padding-left:20px!important;padding-right:20px!important}}
